"""AI agent artifact and interaction models."""
from typing import List, Optional
from pydantic import BaseModel, Field


class TestArtifact(BaseModel):
    """Reproduction PoC or regression unit test generated by Agent Alpha."""
    __test__ = False
    test_file_path: str
    test_code: str
    test_type: str = "reproduction_poc"  # "reproduction_poc" or "regression_unit"
    target_cwe: str = ""
    execution_command: Optional[str] = "pytest"


class PatchCandidate(BaseModel):
    """Candidate code remediation patch generated by Agent Beta."""
    diff_content: str
    target_file: str
    explanation: str = ""
    tombstone_inscription: Optional[str] = None
    model_name: Optional[str] = None


class AuditVerdict(BaseModel):
    """Audit outcome generated by Agent Gamma (Anti-Tamper Auditor)."""
    approved: bool
    violations: List[str] = Field(default_factory=list)
    rejection_reason: Optional[str] = None
    tamper_check_passed: bool = True
    boundary_check_passed: bool = True


class ReflectionFeedback(BaseModel):
    """Actionable diagnostic critique generated by the Reflection Engine."""
    iteration: int
    failure_summary: str
    actionable_critique: str
    failed_tests: List[str] = Field(default_factory=list)
    compiler_errors: List[str] = Field(default_factory=list)
    stack_trace_snippet: Optional[str] = None
